const lockConversationForSystemRunQueueMutation = `-- name: LockConversationForSystemRunQueueMutation :one
WITH parent_lock AS MATERIALIZED (
    SELECT parent.id FROM conversations child JOIN conversations parent ON parent.id=child.channel_id
    WHERE child.id=$1::uuid AND child.company_id=$2::uuid
    FOR NO KEY UPDATE OF parent
)
SELECT conversations.id, conversations.company_id, conversations.kind, conversations.task_id, conversations.schedule_id, conversations.agent_id, conversations.created_by_user_id, conversations.title, conversations.request_key, conversations.pinned_at, conversations.archived_at, conversations.created_at, conversations.updated_at, conversations.version, conversations.head_seq, conversations.is_general, conversations.channel_id, conversations.channel_execution_generation, conversations.channel_context_revision, conversations.project_id, conversations.document_thread_id
FROM conversations
WHERE (SELECT count(*) FROM parent_lock)>=0 AND conversations.id = $1::uuid
  AND conversations.company_id = $2::uuid
FOR NO KEY UPDATE OF conversations
`

type LockConversationForSystemRunQueueMutationParams struct {
	ConversationID uuid.UUID `json:"conversation_id"`
	CompanyID      uuid.UUID `json:"company_id"`
}

// This is a writer mutex, not a key-change lock. Keeping KEY SHARE compatible
// lets a concurrent Run update validate its Conversation foreign key instead
// of queueing behind a terminal writer that is itself waiting for this mutex.
func (q *Queries) LockConversationForSystemRunQueueMutation(ctx context.Context, arg LockConversationForSystemRunQueueMutationParams) (Conversation, error) {
	row := q.db.QueryRow(ctx, lockConversationForSystemRunQueueMutation, arg.ConversationID, arg.CompanyID)
	var i Conversation
	err := row.Scan(
		&i.ID,
		&i.CompanyID,
		&i.Kind,
		&i.TaskID,
		&i.ScheduleID,
		&i.AgentID,
		&i.CreatedByUserID,
		&i.Title,
		&i.RequestKey,
		&i.PinnedAt,
		&i.ArchivedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Version,
		&i.HeadSeq,
		&i.IsGeneral,
		&i.ChannelID,
		&i.ChannelExecutionGeneration,
		&i.ChannelContextRevision,
		&i.ProjectID,
		&i.DocumentThreadID,
	)
	return i, err
}

